(6694979, 1001464, 15711, '<td valign="top">I love that little hint of blue water tying in with the blue tones of his wings and head.  Nice composition.</td>', 'I love that little hint of blue water tying in with the blue tones of his wings and head.  Nice composition.', '2012-02-29 08:24:50.000000', NULL, 1),
(6694980, 1001458, 101256, '<td valign="top">Laughed out loud for this one.  Nice out of the box thinking.  Love the stark black and white tonality even though the white legs seem a little washed out with no detail - legs should have detail. A little more even lighting would have worked well here. Good image and funny title. Well done.</td>', 'Laughed out loud for this one.  Nice out of the box thinking.  Love the stark black and white tonality even though the white legs seem a little washed out with no detail - legs should have detail. A little more even lighting would have worked well here. Good image and funny title. Well done.', '2012-02-29 08:25:05.000000', NULL, 1),
(6694981, 1001550, 15711, '<td valign="top">Oh I love the branches up and over the path!!</td>', 'Oh I love the branches up and over the path!!', '2012-02-29 08:25:18.000000', NULL, 1),
