(6695530, 1001534, 134859, '<td valign="top">Makes me want to go out and shoot a train, which is on my list of things to photograph.  Love the over processed feel here.  Great color choice.  Well done</td>', 'Makes me want to go out and shoot a train, which is on my list of things to photograph.  Love the over processed feel here.  Great color choice.  Well done', '2012-02-29 17:04:17.000000', NULL, 1),
(6695532, 1001014, 134859, '<td valign="top">I''m assuming the foreground is the end of the road, because it looks like the road goes on for miles and miles.  I like the colors here.  It has a warm feeling.  I think it''s a good shot, nicely composed.</td>', 'I''m assuming the foreground is the end of the road, because it looks like the road goes on for miles and miles.  I like the colors here.  It has a warm feeling.  I think it''s a good shot, nicely composed.', '2012-02-29 17:05:08.000000', NULL, 1),
(6695533, 1001454, 134859, '<td valign="top">I like the euphemism.  Believe those are dandelions, though.  <br/> <br/>The light looks a little harsh, which takes away from the photo.  Perhaps selective color desaturation would have helped?</td>', 'I like the euphemism.  Believe those are dandelions, though.   The light looks a little harsh, which takes away from the photo.  Perhaps selective color desaturation would have helped?', '2012-02-29 17:06:08.000000', NULL, 1),
(6695534, 1000479, 134859, '<td valign="top">Love the action shot, especially since you can''t see where he''s going to land... which implies the "gravitationally challenged" title.  Nice focus and detail.</td>', 'Love the action shot, especially since you can''t see where he''s going to land... which implies the "gravitationally challenged" title.  Nice focus and detail.', '2012-02-29 17:06:50.000000', NULL, 1),
(6695535, 1001247, 134859, '<td valign="top">The background object is a little too OOF for me.  I like the idea, and the composition... just wish there wasn''t so much of a blur there.</td>', 'The background object is a little too OOF for me.  I like the idea, and the composition... just wish there wasn''t so much of a blur there.', '2012-02-29 17:07:24.000000', NULL, 1),
(6695538, 1000828, 134859, '<td valign="top">Absolutely gorgeous shot!  This would have been great for the challenge "After the Party".  It gives the feeling that she is drunk... but, she doesn''t look like she is "sick", a little more disgusted look on her face would have done the trick.  I love the photo tho.  9  :)</td>', 'Absolutely gorgeous shot!  This would have been great for the challenge "After the Party".  It gives the feeling that she is drunk... but, she doesn''t look like she is "sick", a little more disgusted look on her face would have done the trick.  I love the photo tho.  9  :)', '2012-02-29 17:08:43.000000', NULL, 1),
(6695539, 1001380, 134859, '<td valign="top">I love it.  The simple wall on the right of the picture playing off of the bricks/stones on the right.  The couple walking in the distance.  The black and white was a fitting choice.  <br/>Great shot!</td>', 'I love it.  The simple wall on the right of the picture playing off of the bricks/stones on the right.  The couple walking in the distance.  The black and white was a fitting choice.  Great shot!', '2012-02-29 17:09:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6695540, 1001027, 134859, '<td valign="top">Not getting the euphemism, BUT... I do like the shot.  I love how the branches are framing the picture.  And the high contrast works well.  Good job</td>', 'Not getting the euphemism, BUT... I do like the shot.  I love how the branches are framing the picture.  And the high contrast works well.  Good job', '2012-02-29 17:10:03.000000', NULL, 1),
(6695542, 1001573, 134859, '<td valign="top">A beautiful, telling photo.  I love the colors, the focus, the detail and blur.  The lighting is spot on.  It''s a wonderful picture.  9</td>', 'A beautiful, telling photo.  I love the colors, the focus, the detail and blur.  The lighting is spot on.  It''s a wonderful picture.  9', '2012-02-29 17:10:51.000000', NULL, 1),
(6695543, 1001379, 134859, '<td valign="top">I get this picture, just don''t understand the processing.  I have looked at it again and again, and my mind is having trouble wrapping around it.  Which is part of the appeal.  It makes you wonder what the artist was thinking... what''s the intention... what''s the story.  The euphemism fits well.  It''s odd... but at the same time, so intriguing.  8</td>', 'I get this picture, just don''t understand the processing.  I have looked at it again and again, and my mind is having trouble wrapping around it.  Which is part of the appeal.  It makes you wonder what the artist was thinking... what''s the intention... what''s the story.  The euphemism fits well.  It''s odd... but at the same time, so intriguing.  8', '2012-02-29 17:12:03.000000', NULL, 1),
(6695544, 1001417, 134859, '<td valign="top">I like the idea here.  If the background was blurred a little, I think it would have really made the buick stand out.</td>', 'I like the idea here.  If the background was blurred a little, I think it would have really made the buick stand out.', '2012-02-29 17:12:38.000000', NULL, 1),
(6695545, 1001148, 134859, '<td valign="top">He looks sad.  It''s like there''s a story behind the picture.  It''s nicely shot.</td>', 'He looks sad.  It''s like there''s a story behind the picture.  It''s nicely shot.', '2012-02-29 17:13:01.000000', NULL, 1),
(6695546, 1000458, 134859, '<td valign="top">Love the pink of the tongue.  I think the dog could have been a little more in focus, but other than that, nice shot.</td>', 'Love the pink of the tongue.  I think the dog could have been a little more in focus, but other than that, nice shot.', '2012-02-29 17:13:40.000000', NULL, 1),
(6695548, 1001127, 134859, '<td valign="top">Interesting way to go.  I like the focus and the background... there''s a very high contrast/saturation to this photo.  Makes it interesting to the viewer.  If there were bees buzzing around the bird, it would have made it an even better shot.  Nicely done.</td>', 'Interesting way to go.  I like the focus and the background... there''s a very high contrast/saturation to this photo.  Makes it interesting to the viewer.  If there were bees buzzing around the bird, it would have made it an even better shot.  Nicely done.', '2012-02-29 17:14:43.000000', NULL, 1),
(6695549, 1001302, 134859, '<td valign="top">It''s a little dark for me.  It was hard for me to tell what it was at first.  But, then I started thinking, I like how the light is playing off of the figurine.  It''s different.  :)</td>', 'It''s a little dark for me.  It was hard for me to tell what it was at first.  But, then I started thinking, I like how the light is playing off of the figurine.  It''s different.  :)', '2012-02-29 17:15:25.000000', NULL, 1),
(6695550, 1001571, 134859, '<td valign="top">I don''t know why, but I love it.  Perhaps it''s the darkness, with hints of light.  Perhaps it''s the glossiness of the tripod... or maybe it''s the fact that it''s a gorilla pod (which I love the one I own).  I think it''s an interesting shot, and a good euphemism.</td>', 'I don''t know why, but I love it.  Perhaps it''s the darkness, with hints of light.  Perhaps it''s the glossiness of the tripod... or maybe it''s the fact that it''s a gorilla pod (which I love the one I own).  I think it''s an interesting shot, and a good euphemism.', '2012-02-29 17:16:29.000000', NULL, 1),
(6695551, 1000690, 134859, '<td valign="top">I like this.  The hint of green in the color is throwing me off.  I also think if the people/background were slightly less in focus it would have made for a better picture.  But good shot overall.</td>', 'I like this.  The hint of green in the color is throwing me off.  I also think if the people/background were slightly less in focus it would have made for a better picture.  But good shot overall.', '2012-02-29 17:17:22.000000', NULL, 1),
(6695564, 1001034, 138683, '<td valign="top">very good, but It looks more like a load of sh*t to me</td>', 'very good, but It looks more like a load of sh*t to me', '2012-02-29 17:46:53.000000', NULL, 1),
(6695573, 1000690, 144913, '<td valign="top">Love it. The dissonance between the lonely man up and the happy folk taking their photos and forgeting all about it. The black &amp; white is very effective</td>', 'Love it. The dissonance between the lonely man up and the happy folk taking their photos and forgeting all about it. The black & white is very effective', '2012-02-29 18:17:56.000000', NULL, 1),
(6695575, 1001014, 144913, '<td valign="top">expressive, mysterious,</td>', 'expressive, mysterious,', '2012-02-29 18:22:10.000000', NULL, 1),
(6695577, 1001313, 144913, '<td valign="top">I like the pun but am not sure about the euphemism. The photo, uneuphemistically, is effective</td>', 'I like the pun but am not sure about the euphemism. The photo, uneuphemistically, is effective', '2012-02-29 18:23:33.000000', NULL, 1),
(6695578, 1001247, 144913, '<td valign="top">just right</td>', 'just right', '2012-02-29 18:23:58.000000', NULL, 1),
(6695579, 1000975, 144913, '<td valign="top">good photo, but not to the euphemistic point</td>', 'good photo, but not to the euphemistic point', '2012-02-29 18:24:52.000000', NULL, 1),
(6695594, 1001521, 144913, '<td valign="top">as a cat-lover, this is a very nice photo (but cats are always so photogenic) and the pun is fun, but no euphemism</td>', 'as a cat-lover, this is a very nice photo (but cats are always so photogenic) and the pun is fun, but no euphemism', '2012-02-29 18:47:11.000000', NULL, 1),
(6695595, 1000932, 144913, '<td valign="top">good juxtapositions (legs, textures, holes) and effective use of the euphemism</td>', 'good juxtapositions (legs, textures, holes) and effective use of the euphemism', '2012-02-29 18:49:17.000000', NULL, 1),
(6695596, 1001574, 144913, '<td valign="top">i like the volume of "waterland" in the middle row of books. The yellow makes one very uncomfortable. So it works!</td>', 'i like the volume of "waterland" in the middle row of books. The yellow makes one very uncomfortable. So it works!', '2012-02-29 18:49:54.000000', NULL, 1),
(6695597, 1001556, 144913, '<td valign="top">ok?</td>', 'ok?', '2012-02-29 18:53:08.000000', NULL, 1),
(6695598, 1000842, 144913, '<td valign="top">it''s so easy to understate (and at the same time laugh at) old age, and the guy isn''t even very old</td>', 'it''s so easy to understate (and at the same time laugh at) old age, and the guy isn''t even very old', '2012-02-29 18:54:14.000000', NULL, 1),
(6695614, 1000975, 132251, '<td valign="top">"OK, when I say 3, kick this heavy metal bucket right at my camera. 1...2..."<br/>Looks like the work of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a>. I think the heavy shadows add to this piece, although I might have cropped out the white door.</td>', '"OK, when I say 3, kick this heavy metal bucket right at my camera. 1...2..."Looks like the work of  jagar. I think the heavy shadows add to this piece, although I might have cropped out the white door.', '2012-02-29 19:16:47.000000', NULL, 1),
