(6696664, 1001034, 118154, '<td valign="top">I like this,over processed and all that but stands out and I like the composition.</td>', 'I like this,over processed and all that but stands out and I like the composition.', '2012-03-01 11:59:14.000000', NULL, 1),
(6696670, 1001521, 118154, '<td valign="top">Liking the lighting and focus here,its in my top ten.</td>', 'Liking the lighting and focus here,its in my top ten.', '2012-03-01 12:02:18.000000', NULL, 1),
